-- GENERATED by `wfj generate` from data/gossip/gossip-63.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["630994914c20f32d"] = { "L'anziano Muggirabbia veglia sul Portale Oscuro da un crinale nelle ⟦Blasted Lands=Terre Devastate⟧.", "." },
  ["630a502a700cb677"] = { "La tua testardaggine condannerà Zephras!", "." },
  ["6313f430627cb54f"] = { "Non farti disturbare dal caldo. Nelle ⟦Badlands=Maleterre⟧, il caldo è l'ultima delle tue preoccupazioni.", "." },
  ["631437af1bd58425"] = { "Avevo tutto! Avevo tutto e poi l'ho perso. Perso... tutto sparito... come... la mia mente. La mia mente è come... il formaggio. Mi piace il formaggio.", "." },
  ["63180f3eed6399c1"] = { "Niente ci distoglierà dalla nostra missione!", "." },
  ["63237b46a51def96"] = { "Esaminando il pilone più da vicino trovi un tavolino con cristalli gialli, rossi e verdi disposti in quella che sembra una formazione precisa.\n\nUn grande cerchio di cristalli gialli è affiancato da un lato da un cerchio più piccolo di cristalli rossi e dall'altro da uno di cristalli verdi.\n\nAnnoti con cura i colori dei cristalli, sapendo che a J.D. interesserebbe molto sapere cosa hai trovato.", "." },
  ["632419adfa2ea29d"] = { "Ero proprio accanto a te, imbecille. So cosa cerchi.", "." },
  ["632ab041747c7123"] = { "Potresti darmi qualche moneta?", "." },
  ["632e58a8ef571d76"] = { "Cerchi una conoscenza più elevata. Tepa è benedetta da tale conoscenza. Dovrebbe essere qui vicino, da qualche parte...", "." },
  ["63331c68673d9178"] = { "Sì, dev'essere Austil de Mon. Se ne sta sempre nella taverna all'estremità sud-est della città. Si chiama ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, non puoi sbagliare.", "." },
  ["635624c4e75949ab"] = { "Magnifico! Le farò mandare subito con un corriere a ⟦Undercity=Sepulcra⟧!\n\nQuanto a te, ecco la paga, come promesso. Tieniti il resto, sudicia bestia!", "." },
  ["635d1cf61926684f"] = { "Tu hai domande, ma sono troppo grandi perché io possa rispondere, {name}. Devi scambiare due parole con l'orco Yelmak, nel Drag di Orgrimmar. Ti aiuterà lui.", "." },
  ["635e9436140580a6"] = { "Sembra che %s non riesca più a lanciare incantesimi. Felcurse sta facendo effetto!", "." },
  ["6362329550d11bb9"] = { "Sono Ulysses Rackmore, capitano del Gallant. E questo è il diario degli ultimi giorni della mia nave condannata.\n\nNavigavamo verso la Roccaforte di Piumaluna con un carico di rifornimenti quando i naga assaltarono le fiancate del Gallant. Li respingemmo, ma sapevamo che sarebbero tornati. Temendo di perdere i miei beni più preziosi, guidai il Gallant verso un'isola al largo di ⟦Desolace=Desolanda⟧, una con antiche rovine degli elfi della notte. E lì lasciai il mio forziere del tesoro.", "." },
  ["636b9a885815d2b9"] = { "Visto cosa intendo? Entra subito.", "." },
  ["636c67a0248dfa00"] = { "Non promette niente di buono!", "." },
  ["636e2ca25052dde6"] = { "%s comincia a evocare un ⟦Blackhand Veteran=Veterano Manonera⟧!", "." },
  ["637660accaa947cd"] = { "Portare questi barili al sito di scavo è un lavoro duro, ma in tanti contano su di noi per far arrivare lì la polvere esplosiva.\n\nDobbiamo fare il possibile contro i Ferroscuro!", "." },
  ["637e46c84c61e0fb"] = { "Le spire della morte ti stritoleranno!", "." },
  ["637f52329139faeb"] = { "Finalmente, uno di voi è degno del mio sapere. Non temere: ho sondato i tuoi pensieri, non ti accadrà nulla di male.", "." },
  ["638283b9588f4ea3"] = { "Sì, l'ho capito solo guardandoti, {name}. Mi ricordi molto me stesso da giovane, quando ero un guerriero dell'⟦Horde=Orda⟧.\n\nSenza dubbio andrai lontano nella vita, e ancora più lontano nella morte.\n\n<Goretooth fa il saluto militare.>", "." },
  ["6382a27f434c2727"] = { "Una corruzione ripugnante si è insinuata nelle ⟦Westfall=Marche Occidentali⟧. Mentre compivo il mio dovere sui campi di battaglia di Lordaeron, queste oneste fattorie sono state invase e trasformate in covi di briganti e assassini. La ⟦People's Militia=Milizia del Popolo⟧ ha bisogno del tuo aiuto.", "." },
  ["638c39269736fe64"] = { "Amici tuoi?", "." },
  ["638d1cdc2b0e1d69"] = { "Rexxar, ho perso l'⟦Drakefire Amulet=Amuleto Fuocodraco⟧. Se ne potrebbe creare un altro?", "." },
  ["638d695ce413ac71"] = { "E resta a terra!", "." },
  ["639019ab179ca3f5"] = { "Non lo permetteremo mai... L'abbiamo già bandito dal nostro mondo una volta e lo bandiremo di nuovo.", "." },
  ["6393c563f1613c8b"] = { "Mi dispiace, ma addestro solo i ladri.", "." },
  ["639b7cec4bd16ffb"] = { "Finalmente la mia anima è libera!", "." },
  ["639d63717491bf0b"] = { "L'⟦Horde=Orda⟧ ha preso la miniera!", "." },
  ["63a2eed0217e73f1"] = { "È stato raccolto tutto e lo stiamo spedendo a ⟦Silithus=Silitus⟧, {class}. Dovrebbe arrivare entro $2113w giorni. Posso solo sperare che, quando il gong sarà suonato e i cancelli aperti, i nostri sforzi qui facciano la differenza e salvino molte vite.", "." },
  ["63a40695969f59fa"] = { "Quando vuoi tu, {name}, si parte. Fai strada!", "." },
  ["63aed17fed8b0ec8"] = { "<Profanatore/Profanatrice>... sarai <punito/punita> per questa incursione. <Un simbolo di fiamma si irradia dalla reliquia prima che si sbricioli a terra.>", "." },
  ["63b12f55accfc261"] = { "Maledetti centauri idioti! Sigh... be', a quanto pare hai mantenuto il patto. Più avanti lungo la strada troverai ⟦Smeed Scrabblescrew=Smeed Torcivite⟧: ha i tuoi soldi.", "." },
  ["63b18d28a667e7fa"] = { "Allora, cosa vuoi fare oggi?", "." },
  ["63b305db24cfaf3e"] = { "Mettere dodici centri di focalizzazione potrebbe permettere alle energie magiche di prendere una forma più solida, aggiungendo la stabilità necessaria.", "." },
  ["63bc2f70838f2b70"] = { "Presto, fratelli! Dovete andare ora! Non so per quanto ancora resterà aperta la fenditura!", "." },
  ["63c4b5a0ce6eb26b"] = { "Apprezzo la compagnia, ma ammettiamolo: con le pozioni hai più esperienza tu di me. Se vuoi addestrarti, parla piuttosto con il dottor Marsh. È un Reietto, nell'Apothecarium di ⟦Undercity=Sepulcra⟧.", "." },
  ["63c71666355672bc"] = { "Ho sentito che i preparativi vengono spediti a ⟦Silithus=Silitus⟧ e dovrebbero arrivare tutti in meno di $2113w giorni. Non voglio vedere uno di quegli insetti scavarsi una galleria fino alla mia miniera, quindi spero che qualcuno si stia prendendo il tempo di ricomporre lo Scettro delle Sabbie Mutevoli, così che il gong venga suonato, i cancelli aperti e la guerra finalmente cominci.", "." },
  ["63c9400850d02b07"] = { "Ah... {name}... la terra è lieta di averti qui.\n\nCon il corpo e lo spirito uniti a lei, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso, la tua essenza.\n\nPresentarti con umiltà davanti alla terra è tutto ciò che ti è richiesto per superare questo rito. Ma gli altri non sono altrettanto passivi. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature duplici che si oppongono l'una all'altra: dovrai imparare a conoscerle a fondo.", "." },
  ["63d0c3cfee154cca"] = { "Di solito i guerrieri si trovano al Pig and Whistle Tavern o alla caserma della Città Vecchia. Però te lo dico, la taverna è probabilmente il posto migliore dove cercare.", "." },
  ["63e6b64c9b713b33"] = { "Siamo arrivati?", "." },
  ["63eb893478cf6f9f"] = { "È l'Occhio che mi ha condotto qui, Eris.", "." },
  ["63ed14612e4765b3"] = { "I pegni d'amore sono piccoli messaggi d'affetto che puoi dare agli abitanti innamorati di paesi e città. Queste persone ti ricompenseranno con un dono d'adorazione.\n\nOppure, se qualcun altro ti adora già, almeno ti daranno un dono d'amicizia.", "." },
  ["63f0b1c90c89e4ff"] = { "Sta' indietro e... trattieni il respiro. Non lo faccio da un po'.", "." },
  ["63f5b9270205bc05"] = { "Per tanto tempo ho vagato in questa forma maledetta. Mi hai liberato... Il tuo duro lavoro sarà ripagato.", "." },
})
